insert into categorias (slug, nombre, descripcion_corta, orden) values ('iluminacion', 'Iluminación', 'Lámparas y veladores', 0) on conflict (slug) do nothing;
insert into categorias (slug, nombre, descripcion_corta, orden) values ('decoracion', 'Decoración', 'Floreros y objetos', 1) on conflict (slug) do nothing;
insert into categorias (slug, nombre, descripcion_corta, orden) values ('organizacion', 'Organización', 'Bandejas y contenedores', 2) on conflict (slug) do nothing;
insert into categorias (slug, nombre, descripcion_corta, orden) values ('jardin', 'Macetas y jardín', 'Macetas e interior verde', 3) on conflict (slug) do nothing;
insert into categorias (slug, nombre, descripcion_corta, orden) values ('personalizados', 'Personalizados', 'A pedido, con tu diseño', 4) on conflict (slug) do nothing;
insert into productos (nombre, categoria_id, precio, colores, material, descripcion, tag, orden) values ('Lámpara Onda', (select id from categorias where slug = 'iluminacion'), 1890, ARRAY['Crudo','Terracota','Grafito']::text[], 'PLA multicolor', 'Lámpara de mesa con capas onduladas que dejan pasar una luz cálida y difusa. Impresa en una sola pieza, sin costuras.', 'Destacado', 0);
insert into productos (nombre, categoria_id, precio, colores, material, descripcion, tag, orden) values ('Velador Strato', (select id from categorias where slug = 'iluminacion'), 1450, ARRAY['Crudo','Piedra']::text[], 'PLA', 'Velador compacto de líneas rectas, pensado para mesa de luz. Zócalo E27, cable textil incluido.', null, 1);
